public void tick() {
        LivingEntity target = tremorsaurus.getTarget();
        if (target != null) {
            boolean grab = isFlyingTarget();
            tremorsaurus.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            tremorsaurus.tryRoar();
            double dist = tremorsaurus.distanceTo(target);
            tremorsaurus.getNavigation().moveTo(target, 1.0D);

            if (dist < tremorsaurus.getBbWidth() + target.getBbWidth() + 1.0D) {
                if (tremorsaurus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    if ((tremorsaurus.getRandom().nextBoolean() || Math.max(target.getBbHeight(), target.getBbWidth()) >= 2.0F) && !grab || tremorsaurus.isBaby()) {
                        tryAnimation(TremorsaurusEntity.ANIMATION_BITE);
                    } else {
                        tryAnimation(TremorsaurusEntity.ANIMATION_SHAKE_PREY);
                    }
                }
            }
            if (tremorsaurus.getAnimation() == TremorsaurusEntity.ANIMATION_BITE) {
                if (tremorsaurus.getAnimationTick() > 10 && tremorsaurus.getAnimationTick() <= 12) {
                    checkAndDealDamage(target);
                }
            }
        }
    }

public void tick() {
        boolean flag = this.inWater;
        if (!flag) {
            FluidState fluidstate = this.dolphin.level().getFluidState(this.dolphin.blockPosition());
            this.inWater = fluidstate.is(FluidTags.LAVA) || fluidstate.is(FluidTags.WATER);
        }
        if(attackCooldown > 0){
            attackCooldown--;
        }
        if (this.inWater && !flag) {
            this.dolphin.playSound(SoundEvents.DOLPHIN_JUMP, 1.0F, 1.0F);
        }
        LivingEntity target = this.dolphin.getTarget();
        if(target != null){
            if(this.dolphin.distanceTo(target) < 3F && attackCooldown <= 0){
                this.dolphin.doHurtTarget(target);
                attackCooldown = 20;
            }
        }

        Vec3 vector3d = this.dolphin.getDeltaMovement();
        if (vector3d.y * vector3d.y < (double) 0.1F && this.dolphin.getXRot() != 0.0F) {
            this.dolphin.setXRot(Mth.rotLerp(this.dolphin.getXRot(), 0.0F, 0.2F));
        } else {
            double d0 = Math.sqrt(vector3d.horizontalDistanceSqr());
            double d1 = Math.signum(-vector3d.y) * Math.acos(d0 / vector3d.length()) * (double) Mth.RAD_TO_DEG;
            this.dolphin.setXRot((float) d1);
        }

    }

